using Stock.Core;
using Stock.Core.Research;
using Stock.Core.Research.Oversold;
using Stock.Core.Trading;
using Stock.Desktop;
internal static partial class Program
{
    private static void DailyPaperCheckpointChecks()
    {
        var now=new DateTimeOffset(2026,11,5,10,0,0,TimeSpan.FromHours(9));var stock=new StockItem("005930","삼성전자",Exchange.KRX,"005930");
        var directory=Path.Combine(output,"daily-checkpoint",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);using var store=new TradingStore(Path.Combine(directory,"state.db"),memoryMarketData:true);
        var days=new[]{new DateOnly(2026,11,3),new DateOnly(2026,11,4),new DateOnly(2026,11,5),new DateOnly(2026,11,6)};var sessions=days.Select(d=>ResearchMarketSession.For(d,Exchange.KRX)).ToArray();
        HistoricalFacts Facts(DailyMarketSession[] dates)=>new(){Source="SYNTHETIC DAILY REPLAY",MarketSessions=dates,StatusRecords=dates.Select(s=>new DailySecurityStatus(stock.Symbol,s.Date,s.Open,HistoricalBoard.Kospi,HistoricalSecurityKind.Common,false,false)).ToArray(),RiskRecords=dates.Select(s=>new FundamentalRiskRecord(stock.Symbol,s.Date,false,s.Open)).ToArray()};var facts=Facts(sessions);
        var config=StrategyDiagnosticPreset.BacktestVerificationPresets()[StrategyDiagnosticPreset.HoldOneDayName].Clone();config.UsePriceOnlyBacktest=false;config.PlannedInvestment=100000;config.InitialCapital=100000;
        var advanced=new StrategyConfiguration{Enabled=true,StrategyType=StrategyType.Box}.Resolve();advanced.Common.Investment=100000;advanced.Execution.OrderType=OrderKind.Limit;advanced.Execution.Commission=0;advanced.Execution.Tax=0;advanced.Execution.SlippagePercent=0;advanced.Execution.OrderTimeoutMilliseconds=20000;
        var baseline=new TradingSettings();baseline.Risk.AccountCapital=100000;baseline.Risk.MaxOrderCash=100000;baseline.Risk.MaxSymbolCash=100000;baseline.Execution.UseSpread=false;baseline.Execution.ParticipationPercent=100;baseline.Execution.LatencyMs=0;baseline.Execution.FeePercent=0;baseline.Execution.SlippagePercent=0;baseline.Data.Universe=stock.Key;var settings=StrategyPresetMapper.ToEngine(advanced,baseline);
        StrategyBar Bar(DailyMarketSession s,decimal close,int index)=>new(new(s.Close,10000,Math.Max(11000,close),9000,close,10000),s.Open,s.Close,index,100_000_000,"SYNTHETIC DAILY REPLAY");
        var plan=new LiveBatchPlan([new(stock,"합성 일봉 복원 검증",settings,100000){Oversold=new(config,new(1,BarUnit.Day),sessions.Take(2).Select((s,n)=>Bar(s,10000,n+1)).ToArray(),facts,PublicPaper:true)}],100000,50000);
        var batch=new RealtimePaperStrategyBatch(store,()=>now);batch.Start(plan);var firstRun=batch.RunId;Check(store.MemoryMarketData&&store.ReadEvents(stock.Key,"NAVER_OBSERVATION",DateTimeOffset.MinValue,DateTimeOffset.MaxValue).Count==0,"daily paper execution creates no raw-tick storage");
        var futureBlocked=false;try{batch.OnPublicBar(stock.Key,Bar(sessions[2],10000,3));}catch(InvalidOperationException){futureBlocked=true;}Check(futureBlocked,"future daily close cannot enter the strategy or its durable decision state");
        now=sessions[2].Close.AddSeconds(1);batch.OnPublicBar(stock.Key,Bar(sessions[2],10000,3));batch.Pulse().GetAwaiter().GetResult();Check(batch.Snapshot().Running&&batch.Snapshot().Rows[0].Pending==0&&store.States("trade-marker:").Count==0,"Day N close records a signal and waits overnight without a same-close fill");
        CurrentMarketSnapshot Quote(decimal price,decimal volume)=>new(stock,new(stock.Name,price,0,0,now,"OPEN"),now,price,price,price,volume,volume*price,"SYNTHETIC_PUBLIC_FIXTURE",TimeSpan.FromSeconds(1));
        now=sessions[3].Open;batch.OnPublicSnapshot(Quote(10000,1000));batch.Pulse().GetAwaiter().GetResult();Check(batch.Snapshot().Rows[0].Pending==10&&batch.Snapshot().Rows[0].Owned==0,"first fresh next-trading-day observation can create a paper order but cannot fill its own triggering observation");
        var restored=new RealtimePaperStrategyBatch(store,()=>now);var notifications=0;restored.FillRecorded+=_=>notifications++;restored.RestoreLatest();Check(!restored.Snapshot().Running&&restored.Snapshot().Rows[0].Pending==10&&notifications==0,"pending paper order restores paused without emitting a duplicate fill");restored.ResumeProtection();
        now=now.AddSeconds(1);restored.OnPublicSnapshot(Quote(10000,1200));restored.Pulse().GetAwaiter().GetResult();Check(restored.Snapshot().Rows[0].Owned==0,"restored quote starts a fresh volume baseline and never invents liquidity from the old cache");
        now=now.AddSeconds(1);restored.OnPublicSnapshot(Quote(9900,1400));restored.Pulse().GetAwaiter().GetResult();Check(restored.Snapshot().Rows[0].Owned==10&&restored.Snapshot().Rows[0].Pending==0&&notifications==1,"later observed liquidity fills the restored order exactly once through the original paper matcher");
        var held=new RealtimePaperStrategyBatch(store,()=>now);held.RestoreLatest();Check(held.Snapshot().Rows[0].Owned==10&&!held.EntryEnabled&&!held.Snapshot().Running,"held quantity, average-cost strategy state and ledger restore with new entries disabled");held.ResumeProtection();
        now=sessions[3].Close.AddSeconds(1);held.OnPublicBar(stock.Key,Bar(sessions[3],11000,4));held.Pulse().GetAwaiter().GetResult();now=new(2026,11,7,10,0,0,TimeSpan.FromHours(9));held.Pulse().GetAwaiter().GetResult();Check(held.Snapshot().Running&&held.Snapshot().Rows[0].Owned==10,"daily position and pending exit survive a weekend without a fictional trading day or liquidation");
        var monday=ResearchMarketSession.For(new(2026,11,9),Exchange.KRX);held.ExtendPublicFacts(stock.Key,Facts([..sessions,monday]));now=monday.Open;held.OnPublicSnapshot(Quote(11000,1000));held.Pulse().GetAwaiter().GetResult();Check(held.Snapshot().Rows[0].Pending==10,"protective exit remains executable after restore although new buys are disabled");now=now.AddSeconds(1);held.OnPublicSnapshot(Quote(11100,1300));held.Pulse().GetAwaiter().GetResult();Check(held.Snapshot().Rows[0].Owned==0&&store.States("trade-marker:").Count==2,"next observed event closes the restored holding and records one buy and one sell");
        var payload=store.State<PaperCheckpointEnvelope>("paper-live-checkpoint:"+firstRun)!;Check(!payload.Payload.Contains("TradeSize")&&!payload.Payload.Contains("NAVER_OBSERVATION")&&!payload.Payload.Contains("PublicSnapshot"),"checkpoint contains decision bars and ledger state, never raw ticks or cached observations");
        var dailyRisk=Serialization.Unpack<PaperBatchCheckpoint>(payload.Payload);Check(dailyRisk.RiskDate==monday.Date&&dailyRisk.OpeningEquity==111000,"daily loss baseline advances from the prior closing valuation and survives checkpoint writes");
        store.State("paper-live-checkpoint:"+firstRun,payload with{Sha256="DAMAGED"});var blocked=false;try{new RealtimePaperStrategyBatch(store,()=>now).RestoreLatest();}catch(InvalidOperationException){blocked=true;}Check(blocked,"damaged checkpoint fails closed instead of silently starting an empty account");store.State("paper-live-checkpoint:"+firstRun,payload);
        var bad=new PaperBroker("KRW",100000,settings.Execution);blocked=false;var frame=Serialization.Unpack<PaperBatchCheckpoint>(payload.Payload);try{bad.Restore(frame.Rows[0].Broker with{Cash=frame.Rows[0].Broker.Cash+1});}catch(InvalidOperationException){blocked=true;}Check(blocked,"cash-conservation check rejects an inconsistent restored ledger");
        held.Stop();held.Start(plan with{Items=plan.Items.Select(i=>i with{Oversold=i.Oversold! with{Facts=Facts([..sessions,monday])}}).ToArray()});Check(held.RunId!=firstRun&&store.State<LiveBatchJournal>("paper-live-batch:"+firstRun)!=null,"a subsequent explicit paper run gets a new ID and preserves the earlier ledger");held.Stop();
    }
}
